type OrganizationInput = {
  name?: InputMaybe<string>;
  email: string;
  VATNumber?: InputMaybe<string>;
  companyRegistrationNumber?: InputMaybe<string>;
  userRegistrationLang?: InputMaybe<string>;
  prefferedOutlet: string;
  city?: InputMaybe<string>;
  street_address?: InputMaybe<string>;
  state?: InputMaybe<string>;
  zip_code?: InputMaybe<string>;
  country?: InputMaybe<string>;
};

export default class CustomerService implements BaseService {
  context: SmartGraphQLContext;

  constructor(context: SmartGraphQLContext) {
    this.context = context;
  }

  async getAllCustomerRequest(bpid?: string): Promise<Customer[]> {
    const requestHeaders: HeaderGetIntegration = {
      ...INTEGRATION_REQUEST_HEADER_BASE,
      'agent-id': this.context.assertedAgentId(),
      'access-token': this.context.assertedAccessToken(),
      'id-token': this.context.assertedIdToken(),
      'outlet-id': bpid ?? '',
    };
    const response = await axios
      .get(endpoints.customer.getAll, {
        params: {
          lang: this.context.assertedLanguage(),
        },
        headers: requestHeaders,
      })
      .catch((e) => {
        logger.error('failed to fetch', { e });
        throw throwCustomError(e);
      });

    const { data } = response;

    const responseData = data['response-data'].data;

    return responseData;
  }

  async getAll(
    input: InputMaybe<AllCustomersInput>
  ): Promise<AllCustomersResponse> {
    const agent = decodeJwtAuthorization(
      this.context.assertedAuthorization(),
      this.context.assertedIdToken()
    );
    const responseData = await this.getAllCustomerRequest(
      agent?.bpId ?? undefined
    );

    let customers = responseData
      .filter((customer) => !!customer.uuid && !!customer.userId)
      .map((customer: Customer) => customer && toSchemaType(customer));

